import * as C from './core.js';

const KEY='clat-pg-study-studio-v1', RECOVERY=KEY+'-recovery';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>C.dayKey(new Date());
const niceDate=d=>new Date(d+'T12:00:00+05:30').toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Kolkata'});
const shortDate=d=>new Date(d+'T12:00:00+05:30').toLocaleDateString('en-IN',{day:'numeric',month:'short',timeZone:'Asia/Kolkata'});
const id=()=>crypto.randomUUID?crypto.randomUUID():String(Date.now())+'-'+Math.random().toString(36).slice(2);
let data,state,sourceMap,questionMap,topicMap,catalog,storageOK=true,recovery=null,route='today';
let recall=null,recallTopic='',libraryQuery='',libraryFilter='all',lastResult=null,compareIndex=0,compareShown=false;
let focusSeconds=25*60,focusDeadline=null,focusTimer=null;
const main=$('#main');

function announce(text){$('#announcer').textContent=text;}
function focusPanel(selector){const node=$(selector);if(node){node.tabIndex=-1;node.focus({preventScroll:true});}}
let toastTimeout;
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('show'),4000);announce(text);}
function storageStatus(){const el=$('#save-status');el.textContent=storageOK?'Saved on this browser':'Not saving · export progress';el.classList.toggle('error',!storageOK);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}storageStatus();updateNav();}
function updateNav(){if(!data)return;$('#nav-due').textContent=data.flashcards.filter(c=>state.cards[c.id]?.dueAt<=Date.now()).length;}
function sourceLinks(ids){return `<div class="source-links">${[...new Set(ids||[])].map(k=>{const s=sourceMap.get(k);return s?`<a href="${h(s.url)}" target="_blank" rel="noopener noreferrer" title="${h(s.pinpoint)}">${h(s.title)} ↗</a>`:'';}).join('')}</div>`;}
function topicOptions(selected='',all='All topics'){return `<option value="">${all}</option>`+data.modules.map(m=>`<option value="${m.id}" ${selected===m.id?'selected':''}>${h(m.title)}</option>`).join('');}
function heading(kicker,title,description,extra=''){return `<div class="page-heading"><div><span class="eyebrow">${h(kicker)}</span><h1>${h(title)}</h1>${description?`<p>${h(description)}</p>`:''}</div>${extra}</div>`;}
function warning(){return storageOK?'':`<div class="storage-warning">Your browser is blocking progress storage. You can still study; export a backup before closing this tab. <button class="text-button" data-action="settings">Open backup settings</button></div>`;}
function empty(title,text,button=''){return `<div class="empty-state"><div class="empty-mark" aria-hidden="true">✧</div><h2>${h(title)}</h2><p>${h(text)}</p>${button}</div>`;}
function topicStats(topicId){const attempts=state.attempts.filter(a=>a.topicId===topicId),n=attempts.length,correct=attempts.filter(a=>a.correct).length;return {n,correct,text:n?`${correct}/${n} practice answers correct`:'Not practised yet'};}
function getPlan(date=today()){return C.planFor(date,state.settings,data.modules.map(m=>m.id));}
function taskKey(name,date=today()){return date+'-'+name;}
function task(name){state.doneTasks[taskKey(name)]=true;}
function taskHtml(name,title,sub){const checked=state.doneTasks[taskKey(name)];return `<label class="task ${checked?'done':''}"><input type="checkbox" data-task="${name}" ${checked?'checked':''}><span>${h(title)}<small>${h(sub)}</small></span></label>`;}
function miniTopic(m,n){const stats=topicStats(m.id);return `<div class="topic-mini"><div><span class="circle">${n}</span><div><strong>${h(m.title)}</strong><small>${h(stats.text)}</small></div></div><a class="button secondary small" href="#learn/${m.id}">Open</a></div>`;}
function renderToday(){
 const plan=getPlan(),left=Math.max(0,plan.left),due=data.flashcards.filter(c=>state.cards[c.id]?.dueAt<=Date.now()).length;
 const reviewed=Object.values(state.cards).filter(c=>c.lastReviewed===today()).length;
 const questions=state.attempts.filter(a=>C.dayKey(new Date(a.at))===today()).length;
 const weak=C.weakTopics(data.modules,state.attempts),focus=(weak.length?weak:plan.focus.map(t=>topicMap.get(t))).filter(Boolean).slice(0,2);
 const newLimit=C.newCardLimit(state.settings.minutes,today(),state.settings.examDate);
 const started=Object.values(state.cards).filter(c=>c.introduced===today()).length;
 const freshLeft=Math.min(data.flashcards.filter(c=>!state.cards[c.id]).length,Math.max(0,newLimit-started));
 const dateNote=plan.left<0?'Your target date has passed. Adjust it in settings to begin another cycle.':plan.left===0?'Exam day: check your admit card, travel plan and the official instructions.':`${plan.phase} · ${state.settings.minutes} minutes planned today`;
 main.innerHTML=warning()+heading('YOUR DAILY STUDY DESK',`Make today count.`,dateNote,`<span class="date-pill">${h(niceDate(today()))}</span>`)+
 `<section class="hero"><div><span class="eyebrow">${h(plan.phase)} / CLAT PG</span><h2>Small sessions.<br>Sharper recall.</h2><p>${plan.left<=3?'Return to the rules you nearly know. Repair recurring errors, practise your pace, and keep the final stretch manageable.':'Don’t just recognise the rule. Retrieve it, distinguish it from its neighbour, and use it in a passage.'}</p><div class="button-row"><a class="button" href="#recall">${due?`Review ${due} due cards`:'Start today’s recall'} <span aria-hidden="true">→</span></a><a class="button secondary" style="color:#d9e6d9;border-color:#7f9d8e" href="#practice">Open practice lab</a></div></div><div class="hero-side"><strong>${left}</strong><span>${left===1?'day to your target':'days to your target'}</span><div class="mini-rule"></div><span>${h(shortDate(state.settings.examDate))} · exam day</span></div></section>
 <section class="stats" aria-label="Your progress"><div class="stat"><span class="stat-label">DUE FOR A RETURN</span><strong>${due}</strong><small>${freshLeft} new cards available today</small></div><div class="stat"><span class="stat-label">RECALLED TODAY</span><strong>${reviewed}</strong><small>distinct cards self-reviewed</small></div><div class="stat"><span class="stat-label">PRACTISED TODAY</span><strong>${questions}</strong><small>original questions attempted</small></div><div class="stat"><span class="stat-label">LESSONS EXPLORED</span><strong>${state.readTopics.length}<small> / ${data.modules.length}</small></strong><small>reading isn’t mastery—keep testing</small></div></section>
 <div class="grid-2"><section class="panel"><div class="section-heading"><h2>Your next four moves</h2><span class="pill green">${state.settings.minutes} min</span></div>${taskHtml('learn','Learn one rule, then close the notes','Open a focus topic and explain the rule in your own words.')}${taskHtml('recall','Retrieve before you reveal','Review due cards first; honest self-ratings keep the queue useful.')}${taskHtml('practice','Use the rule in a timed set','Try a mixed set or one original legal passage.')}${taskHtml('repair','Repair one mistake','Write the rule you missed and retest without the explanation.')}</section><section class="panel"><div class="section-heading"><h2>${weak.length?'Your repair priorities':'Today’s focus topics'}</h2><a href="#learn">View library ↗</a></div>${focus.map((m,i)=>miniTopic(m,String(i+1).padStart(2,'0'))).join('')||'<p class="help">Choose a topic from the library or adjust your target date.</p>'}<div class="content-note">${weak.length?'Based on your recent practice errors, not predicted exam weightage.':'A broad rotation keeps neglected topics in view. Recurrence signals do not guarantee future questions.'}</div><div class="section-heading"><h2>A little uninterrupted time</h2></div><div class="timer-tools"><span class="focus-clock" id="focus-clock">${formatTime(focusSeconds)}</span><button class="button secondary small" data-action="focus-toggle">${focusDeadline?'Pause':'Start 25 min'}</button><button class="text-button" data-action="focus-reset">Reset</button></div></section></div>
 <div class="insight"><strong>A pattern worth practising, not a prediction.</strong>In the working 2022–2026 corpus, all 600 MCQs are passage-linked; 121 have negative-wording cues. Practise passage clusters and check “not”, “except” and similar qualifiers. <a href="#sources">How we use the evidence</a></div>`;
}
function renderLibrary(){
 const modules=data.modules.filter(m=>(m.title+' '+m.description).toLowerCase().includes(libraryQuery.toLowerCase())&&(libraryFilter==='all'||(libraryFilter==='unread'&&!state.readTopics.includes(m.id))||(libraryFilter==='weak'&&C.weakTopics(data.modules,state.attempts).some(w=>w.id===m.id))));
 main.innerHTML=warning()+heading('THE TOPIC LIBRARY','Build a usable legal toolkit.','Short lessons, close distinctions and the traps worth noticing. Read once; then retrieve and apply.')+
 `<div class="filters"><label>Find a topic<input id="library-search" type="search" placeholder="Rights, contracts, evidence…" value="${h(libraryQuery)}"></label><label>Show<select id="library-filter"><option value="all">All topics</option><option value="unread" ${libraryFilter==='unread'?'selected':''}>Not yet explored</option><option value="weak" ${libraryFilter==='weak'?'selected':''}>Practice repair priorities</option></select></label><span class="pill">${modules.length} topics · ${data.flashcards.length} cards</span></div><div id="topic-cards" class="topic-grid">${modules.map((m,i)=>`<article class="card topic-card"><div class="topic-card-top"><span class="topic-num">${String(data.modules.indexOf(m)+1).padStart(2,'0')}</span><span class="pill ${state.readTopics.includes(m.id)?'green':''}">${state.readTopics.includes(m.id)?'Explored':m.minutes+' min lesson'}</span></div><h3>${h(m.title)}</h3><p>${h(m.description)}</p><div class="topic-card-bottom"><small>${h(topicStats(m.id).text)}</small><a href="#learn/${m.id}" class="button secondary small">Study topic →</a></div></article>`).join('')}</div>${modules.length?'':empty('No topics here yet.','Try another search or practise a set to build your repair priorities.')}<div class="insight"><strong>A sprint companion, not an exhaustive textbook.</strong>The library covers foundational rules and distinctions. Keep checked current legal developments and official materials in your revision routine. Sources and statutory-version notes are included with each topic.</div>`;
}
function renderLesson(topicId){
 const m=topicMap.get(topicId);if(!m){location.hash='learn';return;}
 const read=state.readTopics.includes(m.id);
 main.innerHTML=warning()+`<article class="lesson"><a class="back-link" href="#learn">← Back to the topic library</a><span class="eyebrow">TOPIC ${String(data.modules.indexOf(m)+1).padStart(2,'0')} · ${m.minutes} MINUTES</span><h1>${h(m.title)}</h1><p class="intro">${h(m.description)}</p><div class="button-row"><button class="button" data-action="topic-recall" data-topic="${m.id}">Retrieve this topic</button><button class="button secondary" data-action="topic-quiz" data-topic="${m.id}">Try 4 questions</button><button class="text-button" data-action="mark-read" data-topic="${m.id}">${read?'✓ Lesson explored':'Mark lesson explored'}</button></div><p class="help" style="margin-top:18px">${h(m.prerequisite)}</p>
 ${m.sections.map(s=>`<section class="lesson-section"><h2>${h(s.heading)}</h2><p>${h(s.body)}</p></section>`).join('')}
 <section class="lesson-section"><h2>Distinguish the neighbours.</h2><div class="table-wrap"><table><thead><tr><th>One concept</th><th>Its neighbour</th><th>The difference that matters</th></tr></thead><tbody>${m.distinctions.map(d=>`<tr><td>${h(d.left)}</td><td>${h(d.right)}</td><td>${h(d.contrast)}</td></tr>`).join('')}</tbody></table></div></section>
 <section class="lesson-section"><h2>Watch for these traps.</h2><ul class="check-list">${m.pitfalls.map(p=>`<li>${h(p)}</li>`).join('')}</ul></section>
 <section class="panel"><span class="eyebrow">CLOSE THE NOTES FIRST</span><h2>Explain it to your future self.</h2><p class="help">Name the issue, governing rule, decisive fact, exception and conclusion. Change one fact: does your answer change? Your note is private and is not automatically graded.</p><label class="field">Your closed-book explanation<textarea id="lesson-note" placeholder="The rule is… It changes when… A close alternative fails because…">${h(state.notes[m.id]||'')}</textarea></label><button class="button secondary" data-action="save-note" data-topic="${m.id}">Save my explanation</button></section>
 <section class="lesson-section"><h2>Check the primary material.</h2>${sourceLinks(m.sourceIds)}<p class="help" style="margin-top:12px">AI-drafted study summaries with cited sources; qualified legal review is pending. Follow the statute or source version specified in a question.</p></section></article>`;
}
function renderRecall(){
 if(recall&&recall.index<recall.ids.length){renderCard();return;}
 const queue=C.cardQueue(data.flashcards,state),due=data.flashcards.filter(c=>state.cards[c.id]?.dueAt<=Date.now()).length;
 const cap=C.newCardLimit(state.settings.minutes,today(),state.settings.examDate);
 main.innerHTML=warning()+heading('RECALL, THEN REVEAL','Make the rule retrievable.','Try a complete answer before turning the card. Recognition is comfortable; retrieval does the work.')+
 `<div class="grid-equal"><section class="panel"><span class="eyebrow">YOUR SPACED REVIEW</span><h2>${due?`${due} cards are ready to return.`:queue.length?'A small new batch awaits.':'Your queue is clear for now.'}</h2><p class="muted">${queue.length?`Today’s queue has ${due} due cards plus up to ${Math.max(0,queue.length-due)} new ones. Forgotten cards return after ten minutes.`:cap===0?'New cards are paused in the final 72 hours. Use practice sets and return to due cards.':'Come back when cards are due, or use a topic-only self-check without changing your review schedule.'}</p><label class="field">Review topic<select id="recall-topic">${topicOptions(recallTopic)}</select></label><div class="button-row"><button class="button" data-action="start-recall" ${queue.length?'':'disabled'}>Start scheduled recall →</button><button class="button secondary" data-action="free-recall">Topic self-check</button></div><p class="help" style="margin-top:15px">New cards are capped at ${cap}/day for your current plan. Reviewing is self-rated; “easy” is not a mastery certificate.</p></section><section class="panel"><span class="eyebrow">THE CLOSE-DISTINCTION DRILL</span><h2>Similar is not the same.</h2><p class="help">Before revealing the explanation, say what separates the two concepts. This drill does not change card due dates.</p>${comparisonHtml()}</section></div>`;
}
function comparisons(){return data.modules.flatMap(m=>m.distinctions.map(d=>({...d,topicId:m.id})));}
function comparisonHtml(){const list=comparisons(),d=list[compareIndex%list.length];return `<div class="comparison-card"><span class="compare-label">${h(topicMap.get(d.topicId).title)}</span><div class="compare-grid" style="margin-top:15px"><h3>${h(d.left)}</h3><h3>${h(d.right)}</h3></div>${compareShown?`<p>${h(d.contrast)}</p>`:'<p class="help">What changes the legal test or consequence?</p>'}<div class="button-row"><button class="button secondary small" data-action="compare-reveal">${compareShown?'Explanation shown':'Reveal distinction'}</button><button class="text-button" data-action="compare-next">Next pair →</button></div></div>`;}
function startRecall(free=false,topic=recallTopic){
 const pool=data.flashcards.filter(c=>!topic||c.topicId===topic);
 const cards=free?C.shuffle(pool).slice(0,8):C.cardQueue(pool,state);
 if(!cards.length){toast('No scheduled cards in this topic. Choose another topic or use a self-check.');return;}
 recall={ids:cards.map(c=>c.id),index:0,revealed:false,free,attempt:'',spoken:false};location.hash='recall';render();window.scrollTo(0,0);main.focus({preventScroll:true});
}
function renderCard(){
 const card=data.flashcards.find(c=>c.id===recall.ids[recall.index]),m=topicMap.get(card.topicId),p=state.cards[card.id];
 main.innerHTML=warning()+`<div class="flash-space"><div class="session-top"><a href="#recall" data-action="end-recall">← Return to recall desk</a><span>${recall.index+1} / ${recall.ids.length} · ${recall.free?'self-check':p?'returning card':'new card'}</span></div><div class="progress-track"><span style="width:${100*recall.index/recall.ids.length}%"></span></div><section class="flashcard"><span class="eyebrow">${h(m.title)}</span><h1 class="prompt">${h(card.prompt)}</h1>${!recall.revealed?`<label class="field">Try an answer from memory<textarea id="card-attempt" placeholder="Write the rule, condition or distinction before revealing…">${h(recall.attempt)}</textarea></label><label class="task" style="border:0"><input id="card-spoken" type="checkbox" ${recall.spoken?'checked':''}><span>I answered aloud instead.</span></label><button class="button" data-action="reveal-card">Reveal and compare →</button>`:`<section class="answer-block"><span class="eyebrow">COMPARE WITH YOUR ANSWER</span><p class="answer">${h(card.answer)}</p><p class="why">${h(card.why)}</p>${recall.attempt?`<details><summary class="help">Your attempted answer</summary><p class="help">${h(recall.attempt)}</p></details>`:''}${sourceLinks(card.sourceIds)}</section>`}</section>${recall.revealed?`<p class="help" style="margin-top:20px">${recall.free?'Self-check only: choose how it felt to move on. Your due dates stay unchanged.':'Rate your actual recall, not how familiar the answer looks. Dates are capped before your target.'}</p><div class="rating-grid">${['again','hard','good','easy'].map(r=>{const due=C.rateCard(p,r,Date.now(),state.settings.examDate);return `<button class="rating" data-action="rate-card" data-rating="${r}">${{again:'Forgot',hard:'Partial',good:'Recalled',easy:'Effortless'}[r]}<small>${recall.free?'Next card':r==='again'?'Returns in 10 min':due.dueDate===today()?'Final day covered':shortDate(due.dueDate)}</small></button>`;}).join('')}</div>`:'<p class="help" style="text-align:center;margin-top:18px">One clear proposition, one honest attempt. The answer does not need to be word-for-word.</p>'}</div>`;
}
function renderPractice(){
 if(state.quizDraft){renderQuiz();return;}
 if(lastResult){renderResults();return;}
 const weak=C.weakTopics(data.modules,state.attempts);
 main.innerHTML=warning()+heading('THE PRACTICE LAB','Turn knowledge into decisions.','Original educational questions, not reproduced exam items. Choose a focused drill, a mixed set or a passage cluster.')+
 `<div class="practice-grid"><section class="panel"><span class="eyebrow">MIXED RETRIEVAL</span><h2>Choose the rule, not just the option.</h2><div class="filters"><label>Topic<select id="quiz-topic">${topicOptions()}</select></label><label>Questions<select id="quiz-count"><option value="10">10 questions</option><option value="20">20 questions</option><option value="4">4-question quick set</option><option value="64">All ${data.questions.length} questions</option></select></label><label>Time limit<select id="quiz-minutes"><option value="12">12 minutes</option><option value="5">5 minutes</option><option value="25">25 minutes</option><option value="65">65 minutes</option></select></label></div><label class="task" style="border:0"><input id="quiz-simulation" type="checkbox"><span>Simulation mode<small>Hold all explanations until the set ends.</small></span></label><div class="button-row"><button class="button" data-action="start-quiz">Start a practice set →</button><button class="button secondary" data-action="weak-quiz" ${weak.length?'':'disabled'}>Repair weak topics</button></div></section><section class="panel"><span class="eyebrow">HOW TO USE A QUESTION</span><h2>Commit. Check. Correct.</h2><ol class="help"><li>Choose an option and record your confidence before seeing feedback.</li><li>Name the rule and the fact that decides the answer.</li><li>Check the explanation and the closest distractor.</li><li>Repair wrong answers and uncertain correct answers in your notebook.</li></ol><div class="content-note">Scoring: +1 correct, −0.25 wrong, 0 skipped. These original short sets are learning tools, not validated difficulty-matched mock papers.</div><a class="text-button" href="#mistakes">Open the mistake notebook →</a></section></div>
 <div class="section-heading"><h2>Read a passage. Resolve the issue.</h2><span class="pill">${data.passages.length} original sets · 3 questions each</span></div><div class="passage-list">${data.passages.map(p=>`<article class="card passage-card"><span class="eyebrow">${h(topicMap.get(p.topicId)?.title||'Mixed legal reasoning')}</span><h3>${h(p.title)}</h3><p>Original learning scenario · ${p.passage.split(/\s+/).length} words · 3 questions · 6 minutes</p><button class="button secondary small" data-action="start-passage" data-passage="${p.id}">Practise the passage →</button></article>`).join('')}</div><div class="section-heading"><h2>Keep your official-paper results in view.</h2></div><section class="panel"><p class="help">Use a lawfully obtained paper and a checked answer key outside this site. Log the result here; no paper is uploaded. This does not invent question-level mistakes.</p><form id="mock-form"><div class="filters"><label>Paper label<input name="title" required maxlength="150" placeholder="Recent paper / checked key"></label><label>Correct<input name="correct" type="number" min="0" max="120" required></label><label>Wrong<input name="wrong" type="number" min="0" max="120" required></label><label>Skipped<input name="skipped" type="number" min="0" max="120" required></label></div><button class="button secondary" type="submit">Save 120-question paper score</button></form>${historyHtml()}</section>`;
}
function makeQuiz(questions,title,minutes=12,simulation=false,passageId=null){
 if(state.quizDraft&&!confirm('Replace the unfinished set with this one? Saved practice history will stay.'))return;
 state.quizDraft={id:id(),ids:questions.map(q=>q.id),title,answers:questions.map(()=>null),confidences:questions.map(()=>null),committed:questions.map(()=>false),index:0,deadline:Date.now()+minutes*60000,simulation,passageId,passageCollapsed:false};lastResult=null;save();location.hash='practice';render();window.scrollTo(0,0);main.focus({preventScroll:true});
}
function renderQuiz(){
 const quiz=state.quizDraft,q=questionMap.get(quiz.ids[quiz.index]);if(!q){state.quizDraft=null;save();renderPractice();return;}
 const i=quiz.index,committed=quiz.committed[i],feedback=committed&&!quiz.simulation,selected=quiz.answers[i];
 const passage=quiz.passageId?data.passages.find(p=>p.id===quiz.passageId):null;
 main.innerHTML=warning()+`<div class="session-top"><div><span class="eyebrow" style="margin-bottom:4px">${h(quiz.title)}</span>${quiz.simulation?'Simulation: feedback after the set':'Learning: feedback after each commitment'} · Original practice</div><span class="timer" data-timer>${formatTime(Math.max(0,Math.ceil((quiz.deadline-Date.now())/1000)))}</span></div><div class="progress-track"><span style="width:${100*(i+1)/quiz.ids.length}%"></span></div><div class="quiz-layout ${passage?'':'single'}">${passage?`<article class="passage-panel"><span class="eyebrow">ORIGINAL FICTIONAL LEARNING SCENARIO</span><h2>${h(passage.title)}</h2><details data-passage-toggle ${quiz.passageCollapsed?'':'open'}><summary class="help">Passage text: expand or collapse</summary><p>${h(passage.passage)}</p></details></article>`:''}<section class="question-panel"><span class="eyebrow">QUESTION ${i+1} / ${quiz.ids.length} · ${h(topicMap.get(q.topicId)?.title)}</span><h1 class="question-stem">${h(q.stem)}</h1><form id="answer-form"><fieldset style="border:0;padding:0;margin:0"><legend class="sr-only">Choose one answer</legend>${q.options.map((option,n)=>`<label class="option ${selected===n?'selected':''} ${feedback&&q.correctIndex===n?'correct':''} ${feedback&&selected===n&&selected!==q.correctIndex?'wrong':''}"><input type="radio" name="answer" value="${n}" ${selected===n?'checked':''} ${committed?'disabled':''}><span class="option-letter">${'ABCD'[n]}</span><span>${h(option)}</span></label>`).join('')}</fieldset><fieldset class="confidence"><legend>How confident are you before feedback?</legend><div>${['low','medium','high'].map(c=>`<label><input type="radio" name="confidence" value="${c}" ${quiz.confidences[i]===c?'checked':''} ${committed?'disabled':''}>${{low:'Guess / unsure',medium:'Somewhat sure',high:'Very sure'}[c]}</label>`).join('')}</div></fieldset>${!committed?`<button type="submit" class="button">${quiz.simulation?'Save answer':'Commit & check'}</button>`:''}</form>${feedback?feedbackHtml(q,selected,quiz.confidences[i]):committed?'<div class="content-note">Answer saved. Explanation will appear after the set.</div>':''}<div class="quiz-footer"><button class="button secondary small" data-action="quiz-prev" ${i===0?'disabled':''}>← Previous</button>${!committed?`<button class="text-button" data-action="quiz-skip">${i+1===quiz.ids.length?'Leave this item unanswered':'Skip for now →'}</button>`:''}${i+1<quiz.ids.length?`<button class="button small" data-action="quiz-next">Next →</button>`:`<button class="button small" data-action="finish-quiz">Finish set</button>`}</div><div class="button-row"><button class="text-button" data-action="finish-quiz">Submit set now</button><button class="text-button" data-action="discard-quiz">Discard this set</button></div><p class="help" style="margin-top:15px">Your timer continues if you navigate away. A saved set resumes after reload; expiry submits unanswered items as skipped.</p></section></div>`;
}
function feedbackHtml(q,choice,confidence){const correct=choice===q.correctIndex;return `<div class="feedback ${correct?'':'wrong'}" role="status"><h3>${correct?(confidence==='low'?'Correct, but uncertain—worth revisiting.':'Correct. Now check the reasoning.'):'Not quite. Repair the rule, not just the letter.'}</h3><p><strong>${'ABCD'[q.correctIndex]}. ${h(q.options[q.correctIndex])}</strong></p><p>${h(q.explanation)}</p><p class="trap"><strong>Watch the trap:</strong> ${h(q.trap)}</p>${sourceLinks(q.sourceIds)}</div>`;}
function finishQuiz(expired=false){
 const quiz=state.quizDraft;if(!quiz)return;
 if(!expired){const missing=quiz.answers.findIndex((a,i)=>a!==null&&!quiz.confidences[i]);if(missing>=0){quiz.index=missing;save();renderQuiz();toast('Record confidence for each selected answer before submitting.');return;}}
 const qs=quiz.ids.map(q=>questionMap.get(q)),score=C.scoreAnswers(qs,quiz.answers);
 const result={id:quiz.id,title:quiz.title,at:Date.now(),...score};
 if(!state.quizResults.some(r=>r.id===quiz.id)){
  qs.forEach((q,i)=>{if(quiz.answers[i]!==null){state.attempts.push({id:id(),questionId:q.id,topicId:q.topicId,choice:quiz.answers[i],correct:quiz.answers[i]===q.correctIndex,confidence:quiz.confidences[i]||'low',at:Date.now(),reason:'Not classified'});if(state.repairs[q.id])state.repairs[q.id].fixed=quiz.answers[i]===q.correctIndex;}});
  state.quizResults.push(result);task('practice');
 }
 lastResult={...result,questions:qs,answers:quiz.answers,confidences:quiz.confidences,expired};state.quizDraft=null;save();
 if(route==='practice')renderResults();toast(expired?'Time is up. The set was submitted; unanswered items were skipped.':'Set saved. Take a moment to repair the reasoning.');
}
function renderResults(){const r=lastResult;if(!r){renderPractice();return;}
 main.innerHTML=warning()+heading('THE FEEDBACK IS THE WORK',r.expired?'Time is up. Here is your review.':'Keep the rule. Repair the gap.',r.title)+`<section class="panel"><div class="results-head"><div><span class="eyebrow">PRACTICE NET SCORE</span><div class="results-score">${r.net.toFixed(2).replace(/\.00$/,'')}<span> / ${r.questions.length}</span></div></div><div class="small-metrics"><div><strong>${r.correct}</strong><span>correct</span></div><div><strong>${r.wrong}</strong><span>wrong</span></div><div><strong>${r.skipped}</strong><span>skipped</span></div></div></div><div class="button-row"><button class="button" data-action="end-results">Choose another set</button><a href="#mistakes" class="button secondary">Repair mistakes →</a></div><p class="help" style="margin-top:15px">This is a short original learning set; it does not predict your full-paper score. Attempt history is saved; this expanded review remains until you start another set or reload.</p></section><section class="panel" style="margin-top:20px"><h2>Inspect the reasoning.</h2>${r.questions.map((q,i)=>`<details class="review-item"><summary>${i+1}. ${r.answers[i]===null?'○ Skipped':r.answers[i]===q.correctIndex?'✓ Correct':'↺ Repair'} · ${h(q.stem)}</summary><div><p>Your choice: ${r.answers[i]===null?'unanswered':h(q.options[r.answers[i]])}</p>${feedbackHtml(q,r.answers[i],r.confidences[i])}</div></details>`).join('')}</section>`;
}
function historyHtml(){return `<div style="margin-top:20px"><h3>Recent saved sets</h3>${state.quizResults.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Set</th><th>Date</th><th>C / W / S</th><th>Net</th></tr></thead><tbody>${state.quizResults.slice(-8).reverse().map(r=>`<tr><td>${h(r.title)}</td><td>${shortDate(C.dayKey(new Date(r.at)))}</td><td>${r.correct} / ${r.wrong} / ${r.skipped}</td><td>${r.net}</td></tr>`).join('')}</tbody></table></div>`:'<p class="help">Your first completed set will appear here.</p>'}</div>`;}
function mistakes(){const latest=new Map(),flagged=new Set();for(const a of state.attempts){latest.set(a.questionId,a);if(!a.correct||a.confidence==='low')flagged.add(a.questionId);}return [...latest.values()].filter(a=>flagged.has(a.questionId));}
function renderMistakes(){
 const items=mistakes().sort((a,b)=>(a.correct?1:0)-(b.correct?1:0)||(b.confidence==='high'?1:0)-(a.confidence==='high'?1:0)||b.at-a.at);
 main.innerHTML=warning()+heading('THE MISTAKE NOTEBOOK','Every error gets a better rule.','Wrong answers and low-confidence correct answers belong here. Explain the gap, then retest without the solution.')+
 (items.length?`<div class="insight" style="margin-top:0;margin-bottom:25px"><strong>Start with high-confidence errors.</strong>They may expose a rule you are applying too broadly. A marked repair is a note, not proof of mastery; an unseen application is a stronger check.</div>${items.map(a=>{const q=questionMap.get(a.questionId),repair=state.repairs[q.id]||{rule:'',reason:'',fixed:false};return `<article class="panel mistake-card"><div class="button-row" style="margin-top:0"><span class="pill ${a.correct?'amber':''}">${a.correct?(a.confidence==='low'?'Correct but uncertain':'Retested correctly'):a.confidence==='high'?'High-confidence error':'Needs repair'}</span><span class="help">${h(topicMap.get(q.topicId).title)} · ${shortDate(C.dayKey(new Date(a.at)))}</span>${repair.fixed?'<span class="pill green">Retested correctly</span>':''}</div><h3>${h(q.stem)}</h3><p class="help">Your latest choice: ${h(q.options[a.choice])}</p><details><summary class="help">Review the source-backed explanation</summary>${feedbackHtml(q,a.choice,a.confidence)}</details><div class="repair"><label class="field">What caused the miss?<select data-repair-reason="${q.id}">${['Not classified','Rule unknown','Exception missed','Passage misread','Negation missed','Distractor confusion','Time pressure','Uncertain guess'].map(v=>`<option ${repair.reason===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Write the corrected rule and its exception<textarea data-repair-rule="${q.id}" placeholder="The decisive rule is… It does not apply when…">${h(repair.rule)}</textarea></label><div class="button-row"><button class="button secondary small" data-action="save-repair" data-question="${q.id}">Save repair note</button><button class="button small" data-action="retest" data-question="${q.id}">Retest without the answer →</button></div></div></article>`;}).join('')}`:empty('A clean page, for now.','Finish a practice set first. Errors and uncertain correct answers will appear here.',`<div class="button-row"><a class="button" href="#practice">Start a practice set</a></div>`));
}
function renderPlan(){
 const total=C.daysBetween(state.settings.startDate,state.settings.examDate),max=Math.min(total,90);
 main.innerHTML=warning()+heading('A FINITE, ADAPTABLE PLAN','Nineteen days. One useful loop.','Your target is editable. The default plan covers 17 November–5 December, with exam day on 6 December.',`<button class="button secondary small" data-action="settings">Adjust the plan</button>`)+
 `<div class="grid-equal"><section class="panel"><span class="eyebrow">THE DAILY BALANCE</span><h2>${state.settings.minutes} minutes, deliberately spent.</h2><ul class="check-list"><li>${Math.round(state.settings.minutes*.3)} min: focused topic learning and closed-book explanation</li><li>${Math.round(state.settings.minutes*.2)} min: due flashcards and brief retrieval</li><li>${Math.round(state.settings.minutes*.3)} min: timed questions or a passage cluster</li><li>${state.settings.minutes-Math.round(state.settings.minutes*.3)*2-Math.round(state.settings.minutes*.2)} min: feedback, repair notes and rechecks</li></ul><p class="help">A starting template, not an empirically optimal allocation. Switch topic-learning time toward revision in the final days. Your daily card cap prevents an unmanageable new-card queue.</p></section><section class="panel"><span class="eyebrow">IN THE FINAL 72 HOURS</span><h2>Consolidate. Don’t collect.</h2><p class="help">New cards pause by default. Return to due cards, high-confidence errors, rule–exception contrasts and your own short summaries. Use timed practice to check pacing. Keep the evening before the exam light and check official travel/admit-card instructions.</p><div class="content-note">Reading completion and self-ratings are activity signals, not predictions of marks. Record whole-paper performance with checked keys in the practice lab.</div><a class="text-button" href="#practice">Log or practise a set →</a></section></div><div class="section-heading"><h2>Your calendar</h2><span class="pill">${total} study days · exam ${h(shortDate(state.settings.examDate))}</span></div>${total>90?'<p class="help">Showing the first 90 days. Shorten the plan window to use a focused sprint.</p>':''}<div class="calendar">${Array.from({length:max},(_,i)=>{const date=C.addDays(state.settings.startDate,i),p=getPlan(date),isToday=date===today();const focus=p.focus.map(t=>topicMap.get(t)?.title).join(' + ');return `<article class="day-card ${isToday?'today':date<today()?'past':''}"><span class="eyebrow" style="margin-bottom:5px">DAY ${i+1} ${isToday?'· TODAY':''}</span><h3>${h(shortDate(date))}</h3><p><strong>${h(p.phase)}</strong><br>${p.left<=3?'Due recall, error repair and pacing.':h(focus)}</p><label><input type="checkbox" data-day="${date}" ${state.doneTasks[taskKey('day',date)]?'checked':''}>Day reviewed</label></article>`;}).join('')}</div><div class="insight"><strong>Build → mix → consolidate.</strong>Topic rotation is an editorial plan. Move weak topics forward based on your practice errors; do not read historical cue counts as guaranteed paper allocations.</div>`;
}
function renderSources(){
 main.innerHTML=heading('THE REASONING BEHIND THE STUDIO','Know what you are relying on.','A transparent learning design, linked legal sources and clear boundaries around the historical patterns.')+
 `<section class="panel"><h2>Exam target, checked 17 November 2026.</h2><p class="help">CLAT PG 2027: 6 December 2026, 2–4 pm under the general schedule; eligible PwD timing differs in the official instructions. 120 objective questions, +1 correct and −0.25 wrong. The official syllabus expects legal-extract comprehension, related knowledge and application. Check the official pages for revisions.</p>${sourceLinks(data.learning.exam.sourceIds)}</section>
 <section class="panel" style="margin-top:20px"><h2>Learning methods we put into practice.</h2>${data.learning.methods.map(m=>`<article class="method"><h3>${h(m.title)}</h3><p>${h(m.principle)}</p><p><strong>In this studio:</strong> ${h(m.implementation)}</p><p class="help"><strong>Boundary:</strong> ${h(m.limits)}</p>${sourceLinks(m.sourceIds)}</article>`).join('')}<div class="content-note">The 1/3/7-day progression, card caps, daily allocations and last-72-hour taper are transparent design heuristics. They are not a validated CLAT optimisation algorithm or a promise of a score increase.</div></section>
 <section class="panel" style="margin-top:20px"><h2>What the paper analysis supports.</h2><p class="help">The working extraction contains 1,387 MCQs across 2016–2026 year labels. All 600 recent MCQs (2022–2026) link to passages; 121 have negative-wording cues. Topic indicators overlap and are lexical, not reviewed subject weightages; 248/600 recent stems have no topic-rule match. Corpus completeness, 2019 coverage, 2024 set correspondence and unique administrations remain unresolved. Independent subject coding and legal adjudication are pending.</p><p class="help">This public site distributes original educational lessons and fictional scenarios, plus aggregate observations. It contains no scanned papers, extracted exam questions, raw annotations or inferred official answers. A shared theme is not an exact repeat. Low historical counts do not justify dropping a syllabus topic.</p><h3>Content status</h3><p class="help">AI-assisted original teaching summaries and questions, with source references; not independently or professionally adjudicated legal material. Use the cited primary text and the applicable date/version when checking an answer. Foundational coverage is selective; this is not a complete substitute for the syllabus, current developments or checked official practice materials. Researcher/team attribution remains TO CONFIRM.</p><h3>Your progress stays with you.</h3><p class="help">No account, analytics or server-side progress collection. Progress is stored in this browser’s local storage. Clearing browser data removes it. Export JSON backups regularly; import replaces local progress after validation. Opening a source link visits its external website. Timer and due dates use your device clock; the study calendar uses India time.</p></section>
 <div class="section-heading"><h2>The source shelf</h2><span class="pill">${sourceMap.size} references</span></div>${[...sourceMap.values()].map(s=>`<article class="panel source-card"><span class="eyebrow">${h(s.kind)} · CHECKED ${h(s.accessed)}</span><h3>${h(s.title)}</h3><p class="muted">${h(s.pinpoint)}</p><a href="${h(s.url)}" target="_blank" rel="noopener noreferrer">Open primary source ↗</a>${s.verification?`<p class="help">${h(s.verification)}</p>`:''}</article>`).join('')}`;
}
function settings(){
 const dialog=$('#settings-dialog');dialog.innerHTML=`<div class="dialog-top"><div><span class="eyebrow">YOUR PLAN, YOUR PROGRESS</span><h2 id="settings-heading">Set up your study desk.</h2></div><button class="icon-button" data-action="close-settings" aria-label="Close settings">×</button></div><form id="settings-form"><div class="dialog-grid"><label class="field">Plan starts<input type="date" name="startDate" value="${state.settings.startDate}" required></label><label class="field">Exam date<input type="date" name="examDate" value="${state.settings.examDate}" required></label></div><label class="field">Available study time per day<select name="minutes">${[60,90,120,180,240,300].map(n=>`<option value="${n}" ${state.settings.minutes===n?'selected':''}>${n} minutes</option>`).join('')}</select></label><p class="help">Default target: CLAT PG, 6 December 2026. Changing the date changes the plan and new-card taper; already scheduled review dates are retained.</p><button class="button" type="submit">Save plan</button></form><hr class="divider"><h3>Back up before you clear a browser.</h3><p class="help">Progress is private to this browser and this website address. Export it to move between devices. Import replaces current progress only after validation and confirmation.</p><div class="button-row"><button class="button secondary" data-action="export">Export my progress</button><label class="button secondary">Import backup<input id="import-file" type="file" accept="application/json,.json" class="sr-only"></label></div>${recovery?'<div class="button-row"><button class="text-button" data-action="export-recovery">Download unreadable earlier data</button></div>':''}<p class="help" id="import-status" role="status" style="margin-top:15px"></p><hr class="divider"><div class="danger-zone"><h3>Start over on this browser</h3><p class="help">This removes cards, notes and practice history. Export a backup first.</p><button class="button danger small" data-action="reset">Reset all progress</button></div>`;dialog.showModal();
}
function exportData(raw=null,name='clat-pg-progress'){const blob=new Blob([raw??JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name+'-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Backup downloaded. Keep it somewhere you can find it.');}
function formatTime(seconds){return `${Math.floor(Math.max(0,seconds)/60).toString().padStart(2,'0')}:${(Math.max(0,seconds)%60).toString().padStart(2,'0')}`;}
function render(){
 const parts=location.hash.slice(1).split('/');route=parts[0]||'today';
 $$('#navigation a').forEach(a=>{const active=a.dataset.route===route;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 $('#top-context').textContent=`CLAT PG · ${niceDate(state.settings.examDate)} · ${Math.max(0,C.daysBetween(today(),state.settings.examDate))} days to go`;
 const renderers={today:renderToday,learn:()=>parts[1]?renderLesson(parts[1]):renderLibrary(),recall:renderRecall,practice:renderPractice,mistakes:renderMistakes,plan:renderPlan,sources:renderSources};
 (renderers[route]||renderToday)();updateNav();
}
document.addEventListener('click',event=>{
 const button=event.target.closest('[data-action]');if(!button||!state)return;
 const action=button.dataset.action,t=button.dataset.topic;
 if(action==='settings'){settings();return;}if(action==='close-settings'){$('#settings-dialog').close();return;}
 if(action==='export'){exportData();return;}if(action==='export-recovery'){exportData(recovery,'clat-unreadable-recovery');return;}
 if(action==='reset'){if(confirm('Remove all study progress on this browser? This cannot be undone without a backup.')){state=C.freshState();recall=null;lastResult=null;save();$('#settings-dialog').close();render();toast('A fresh study desk is ready.');}return;}
 if(action==='mark-read'){if(!state.readTopics.includes(t))state.readTopics.push(t);task('learn');save();renderLesson(t);toast('Lesson explored. Now test what you can retrieve.');return;}
 if(action==='save-note'){state.notes[t]=$('#lesson-note').value.slice(0,20000);task('learn');save();toast('Your explanation is saved on this browser.');return;}
 if(action==='topic-recall'){recallTopic=t;startRecall(false,t);return;}
 if(action==='topic-quiz'){makeQuiz(data.questions.filter(q=>q.topicId===t),topicMap.get(t).title,6);return;}
 if(action==='start-recall'){recallTopic=$('#recall-topic').value;startRecall();return;}
 if(action==='free-recall'){recallTopic=$('#recall-topic').value;startRecall(true);return;}
 if(action==='end-recall'){event.preventDefault();recall=null;renderRecall();return;}
 if(action==='reveal-card'){recall.attempt=$('#card-attempt').value.trim();recall.spoken=$('#card-spoken').checked;if(!recall.attempt&&!recall.spoken){toast('Try an answer first, or confirm that you answered aloud.');return;}recall.revealed=true;renderCard();focusPanel('.answer-block');announce('Answer revealed. Compare it with your attempted answer.');return;}
 if(action==='rate-card'){const cardId=recall.ids[recall.index];if(!recall.free){state.cards[cardId]=C.rateCard(state.cards[cardId],button.dataset.rating,Date.now(),state.settings.examDate);task('recall');save();}recall.index++;recall.revealed=false;recall.attempt='';recall.spoken=false;if(recall.index>=recall.ids.length){recall=null;renderRecall();toast('Session complete. Return later for spaced reviews.');}else renderCard();return;}
 if(action==='compare-reveal'){compareShown=true;renderRecall();return;}
 if(action==='compare-next'){compareIndex++;compareShown=false;renderRecall();return;}
 if(action==='start-quiz'){const topic=$('#quiz-topic').value,pool=data.questions.filter(q=>!topic||q.topicId===topic),n=Number($('#quiz-count').value);makeQuiz(C.shuffle(pool).slice(0,n),topic?topicMap.get(topic).title:'Mixed-topic retrieval',Number($('#quiz-minutes').value),$('#quiz-simulation').checked);return;}
 if(action==='weak-quiz'){const topics=C.weakTopics(data.modules,state.attempts).slice(0,3).map(m=>m.id);makeQuiz(C.shuffle(data.questions.filter(q=>topics.includes(q.topicId))).slice(0,10),'Weak-topic repair',12);return;}
 if(action==='start-passage'){const p=data.passages.find(p=>p.id===button.dataset.passage);makeQuiz(p.questions,p.title,6,false,p.id);return;}
 if(action==='quiz-prev'){state.quizDraft.index--;save();renderQuiz();window.scrollTo(0,0);focusPanel('.question-stem');return;}
 if(action==='quiz-next'){state.quizDraft.index++;save();renderQuiz();window.scrollTo(0,0);focusPanel('.question-stem');return;}
 if(action==='quiz-skip'){const q=state.quizDraft;if(!q.committed[q.index]){q.answers[q.index]=null;q.confidences[q.index]=null;}if(q.index+1<q.ids.length){q.index++;save();renderQuiz();}else{save();toast('Item left unanswered. Finish the set when ready.');renderQuiz();}return;}
 if(action==='finish-quiz'){finishQuiz();return;}
 if(action==='discard-quiz'){if(confirm('Discard this unfinished set? Completed history will stay.')){state.quizDraft=null;save();renderPractice();}return;}
 if(action==='end-results'){lastResult=null;renderPractice();return;}
 if(action==='save-repair'){const qid=button.dataset.question,rule=$(`[data-repair-rule="${qid}"]`).value.trim(),reason=$(`[data-repair-reason="${qid}"]`).value;if(!rule){toast('Write a corrected rule before saving.');return;}state.repairs[qid]={rule:rule.slice(0,20000),reason,fixed:state.repairs[qid]?.fixed||false};task('repair');save();toast('Repair saved. Retest without opening the explanation.');return;}
 if(action==='retest'){const q=questionMap.get(button.dataset.question);makeQuiz([q],'One-rule recheck',2);return;}
 if(action==='focus-toggle'){if(focusDeadline){focusSeconds=Math.max(0,Math.ceil((focusDeadline-Date.now())/1000));focusDeadline=null;button.textContent='Resume';}else{focusDeadline=Date.now()+focusSeconds*1000;button.textContent='Pause';}return;}
 if(action==='focus-reset'){focusDeadline=null;focusSeconds=25*60;renderToday();return;}
});
document.addEventListener('change',async event=>{
 const el=event.target;if(!state)return;
 if(el.dataset.task){state.doneTasks[taskKey(el.dataset.task)]=el.checked;save();el.closest('.task').classList.toggle('done',el.checked);}
 if(el.dataset.day){state.doneTasks[taskKey('day',el.dataset.day)]=el.checked;save();}
 if(el.id==='library-filter'){libraryFilter=el.value;renderLibrary();}
 if(el.name==='answer'&&state.quizDraft){state.quizDraft.answers[state.quizDraft.index]=Number(el.value);save();$$('.option').forEach(o=>o.classList.toggle('selected',$('input',o).checked));}
 if(el.name==='confidence'&&state.quizDraft){state.quizDraft.confidences[state.quizDraft.index]=el.value;save();}
 if(el.id==='import-file'&&el.files[0]){
  const status=$('#import-status'),file=el.files[0];
  if(file.size>5*1024*1024){status.textContent='This backup is too large (maximum 5 MB). Current progress is unchanged.';return;}
  try{const imported=JSON.parse(await file.text()),check=C.validateState(imported,catalog);if(!check.ok)throw new Error(check.error);
   if(imported.quizDraft?.passageId&&!data.passages.some(p=>p.id===imported.quizDraft.passageId))throw new Error('Unknown passage in backup.');
   if(!confirm('Replace this browser’s progress with this backup? Export current progress first if needed.')){status.textContent='Import cancelled. Current progress is unchanged.';return;}
   state=imported;recall=null;lastResult=null;save();$('#settings-dialog').close();render();toast('Backup imported. Your study desk is restored.');
  }catch(error){status.textContent='Import rejected: '+error.message+' Current progress is unchanged.';}finally{el.value='';}
 }
});
document.addEventListener('toggle',event=>{if(event.target.matches?.('[data-passage-toggle]')&&state?.quizDraft){state.quizDraft.passageCollapsed=!event.target.open;save();}},true);
document.addEventListener('input',event=>{
 if(event.target.id==='library-search'){libraryQuery=event.target.value;const start=event.target.selectionStart;renderLibrary();const field=$('#library-search');field.focus();field.setSelectionRange(start,start);}
});
document.addEventListener('submit',event=>{
 const form=event.target;event.preventDefault();if(!state)return;
 if(form.id==='answer-form'){const quiz=state.quizDraft,i=quiz.index;if(quiz.answers[i]===null){toast('Choose an answer, or skip this item.');return;}if(!quiz.confidences[i]){toast('Record your confidence before seeing the answer.');return;}quiz.committed[i]=true;save();renderQuiz();focusPanel(quiz.simulation?'.question-stem':'.feedback');if(!quiz.simulation)announce(quiz.answers[i]===questionMap.get(quiz.ids[i]).correctIndex?'Correct. Check the explanation.':'Incorrect. The explanation is ready.');else toast('Answer saved. Continue to the next question.');}
 if(form.id==='settings-form'){const fields=new FormData(form),s={...state,settings:{startDate:fields.get('startDate'),examDate:fields.get('examDate'),minutes:Number(fields.get('minutes'))}},check=C.validateState(s,catalog);if(!check.ok){toast(check.error);return;}state=s;save();$('#settings-dialog').close();render();toast('Plan updated. Scheduled card dates are retained.');}
 if(form.id==='mock-form'){const fields=new FormData(form),correct=Number(fields.get('correct')),wrong=Number(fields.get('wrong')),skipped=Number(fields.get('skipped'));if(![correct,wrong,skipped].every(n=>Number.isInteger(n)&&n>=0)||correct+wrong+skipped!==120){toast('Correct, wrong and skipped must total 120.');return;}state.quizResults.push({id:id(),title:'Paper log: '+fields.get('title').trim(),at:Date.now(),correct,wrong,skipped,net:correct-.25*wrong});save();renderPractice();toast('Paper score saved. Question-level history was not inferred.');}
});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);main.focus({preventScroll:true});});
window.addEventListener('storage',e=>{if(e.key===KEY)toast('Progress changed in another tab. Reload before continuing to avoid overwriting it.');});
setInterval(()=>{
 if(state?.quizDraft){const remaining=Math.max(0,Math.ceil((state.quizDraft.deadline-Date.now())/1000)),timer=$('[data-timer]');if(timer){timer.textContent=formatTime(remaining);timer.classList.toggle('urgent',remaining<60);}if(remaining<=0)finishQuiz(true);}
 if(focusDeadline){focusSeconds=Math.max(0,Math.ceil((focusDeadline-Date.now())/1000));const clock=$('#focus-clock');if(clock)clock.textContent=formatTime(focusSeconds);if(focusSeconds===0){focusDeadline=null;toast('Focus block complete. Take a short break and check your next move.');}}
},1000);
async function init(){
 try{
  const files=await Promise.all(['content-foundations.json','content-breadth.json','learning-evidence.json'].map(async p=>{const r=await fetch(new URL(p,import.meta.url));if(!r.ok)throw new Error('Could not load '+p);return r.json();}));
  const [a,b,learning]=files;data={modules:[...a.modules,...b.modules],flashcards:[...a.flashcards,...b.flashcards],questions:[...a.questions,...b.questions],passages:[...a.passages,...b.passages],learning};
  sourceMap=new Map([...a.sources,...b.sources,...learning.sources].map(s=>[s.id,s]));topicMap=new Map(data.modules.map(m=>[m.id,m]));questionMap=new Map([...data.questions,...data.passages.flatMap(p=>p.questions)].map(q=>[q.id,q]));
  catalog={cardIds:new Set(data.flashcards.map(c=>c.id)),questionIds:new Set(questionMap.keys()),topicIds:new Set(topicMap.keys())};
  state=C.freshState();
  try{const raw=localStorage.getItem(KEY);recovery=localStorage.getItem(RECOVERY);if(raw){try{const parsed=JSON.parse(raw),check=C.validateState(parsed,catalog);if(!check.ok)throw new Error(check.error);state=parsed;}catch{recovery=raw;localStorage.setItem(RECOVERY,raw);toast('Earlier progress could not be read. Its original data can be downloaded in settings.');}}localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;}
  storageStatus();render();if(state.quizDraft&&state.quizDraft.deadline<=Date.now())finishQuiz(true);
 }catch(error){main.innerHTML=empty('The library could not load.','Serve the site over HTTP (including GitHub Pages), then reload. If you are offline on a first visit, reconnect. No progress has been erased.');console.error(error);}
}
init();
